-- domain is frozen. adding a value is a PRD change.
create type recon.exception_code as enum (
  'PRICE','QTY','CUSIP','SIDE','LATE','OTHER'
);

alter table recon.break
  add column exception_code recon.exception_code,
  add column exception_subtype text,
  add column legacy_uncoded boolean not null default false;

create table recon.break_reason_history (
  id bigserial primary key,
  break_id bigint not null references recon.break(id),
  at timestamptz not null default now(),
  actor_email text not null,
  actor_display text not null,
  from_code recon.exception_code,
  to_code recon.exception_code,
  from_subtype text,
  to_subtype text,
  note text,
  ui_session_id uuid,
  immutable hashbytea generated always as (
    digest(break_id::text || at::text || actor_email || coalesce(to_code::text,'') || coalesce(note,''), 'sha256')
  ) stored
);
create index on recon.break_reason_history (break_id, at desc);
-- no update, no delete grants to recon_app
revoke update, delete on recon.break_reason_history from recon_app;
grant insert, select on recon.break_reason_history to recon_app;

-- trigger: any change to exception_code/subtype/note inserts history
-- do not update history rows. there is no update path.
